# =============================================================================
# Sheet "prevoditelnost_cash_trn" má jeden řádek per POBOCKA+POHYB+PREVODITELNOST_LOG
# — používáme ho přímo v pobočkových reportech pro detail operací.

hotovostni_trn_detail = None
try:
    _path_trn = soubory["hotovostni_trn"]["path"]
    _df_log = pd.read_excel(_path_trn, sheet_name="prevoditelnost_cash_trn")
    _df_log = normalize_columns(_df_log)

    _log_id   = next((c for c in ['POBOCKA','BRANCH_CODE','POBOCKA_ID'] if c in _df_log.columns), None)
    _log_poh  = next((c for c in ['POHYB','TYP_POHYBU'] if c in _df_log.columns), None)
    _log_prv  = next((c for c in ['PREVODITELNOST','PREV'] if c in _df_log.columns), None)
    _log_col  = next((c for c in ['PREVODITELNOST_LOG','POPIS_OPERACE'] if c in _df_log.columns), None)
    _log_cas  = next((c for c in ['SUM_CASTKA_TRANSAKCE','CASTKA','SUM_CASTKA'] if c in _df_log.columns), None)
    _log_poc  = next((c for c in ['POCET_OPERACI','POCET'] if c in _df_log.columns), None)

    if all(x for x in [_log_id, _log_poh, _log_prv, _log_cas, _log_poc]):
        _df_log[_log_id]  = pd.to_numeric(_df_log[_log_id],  errors='coerce')
        _df_log[_log_poh] = _df_log[_log_poh].astype(str).str.strip().str.upper()
        _df_log[_log_prv] = _df_log[_log_prv].astype(str).str.strip().str.upper()
        _df_log[_log_cas] = pd.to_numeric(_df_log[_log_cas], errors='coerce').fillna(0)
        _df_log[_log_poc] = pd.to_numeric(_df_log[_log_poc], errors='coerce').fillna(0)
        hotovostni_trn_detail = _df_log.rename(columns={
            _log_id:  'POBOCKA', _log_poh: 'POHYB', _log_prv: 'PREVODITELNOST',
            _log_cas: 'SUM_CASTKA_TRANSAKCE', _log_poc: 'POCET_OPERACI',
            **({_log_col: 'PREVODITELNOST_LOG'} if _log_col else {}),
        })
        _load_log.append({"jmeno": "hotovostni_trn_detail", "status": "✅", "typ": "XLSX",
            "řádků": f"{len(hotovostni_trn_detail):,}",
            "sloupců": str(len(hotovostni_trn_detail.columns)),
            "platnost": "", "pozn": f"{hotovostni_trn_detail['POBOCKA'].nunique()} poboček, sheet prevoditelnost_cash_trn"})
    else:
        _load_log.append({"jmeno": "hotovostni_trn_detail", "status": "⚠️", "typ": "XLSX",
            "řádků": "—", "sloupců": "—", "platnost": "", "pozn": f"chybí povinné sloupce: {list(_df_log.columns)}"})
except Exception as e:
    _load_log.append({"jmeno": "hotovostni_trn_detail", "status": "⚠️", "typ": "XLSX",
        "řádků": "—", "sloupců": "—", "platnost": "", "pozn": str(e)})


# =============================================================================
# 1c. AGREGACE HOTOVOSTNÍCH TRANSAKCÍ PRO CASH RATING (CASH_IN + CASH_OUT + OTHER)
# =============================================================================

try:
    _trn = hotovostni_trn.copy()
    id_col     = next((c for c in ['POBOCKA', 'BRANCH_CODE', 'POBOCKA_ID'] if c in _trn.columns), None)
    castka_col = next((c for c in ['SUM_CASTKA_TRANSAKCE', 'CASTKA', 'SUM_CASTKA'] if c in _trn.columns), None)
    pocet_col  = next((c for c in ['POCET_OPERACI', 'POCET', 'POCET_TRANSAKCI'] if c in _trn.columns), None)

    if not all([id_col, castka_col, pocet_col]):
        raise ValueError(f"Chybí sloupce. Dostupné: {list(_trn.columns)}")

    _trn[id_col]     = pd.to_numeric(_trn[id_col],     errors='coerce')
    _trn[castka_col] = pd.to_numeric(_trn[castka_col], errors='coerce').fillna(0)
    _trn[pocet_col]  = pd.to_numeric(_trn[pocet_col],  errors='coerce').fillna(0)
    _trn = _trn.dropna(subset=[id_col])

    transakce_trn_agg = (
        _trn.groupby(id_col)
        .agg(TRN_POCET_CELKEM=(pocet_col, 'sum'),
             TRN_CASTKA_CELKEM=(castka_col, 'sum'))
        .reset_index()
        .rename(columns={id_col: 'BRANCH_CODE'})
    )
    transakce_trn_agg['BRANCH_CODE']     = transakce_trn_agg['BRANCH_CODE'].astype(int)
    transakce_trn_agg['TRN_DENNI_POCET'] = (transakce_trn_agg['TRN_POCET_CELKEM'] / WORKING_DAYS_PER_YEAR).round(1)

    _load_log.append({"jmeno": "transakce_trn_agg", "status": "✅", "typ": "agg",
        "řádků": f"{len(transakce_trn_agg):,}", "sloupců": "3",
        "platnost": "", "pozn": f"cash rating agregát, {int(transakce_trn_agg['TRN_POCET_CELKEM'].sum()):,} transakcí celkem"})

except Exception as e:
    import traceback
    _load_log.append({"jmeno": "transakce_trn_agg", "status": "❌", "typ": "agg",
        "řádků": "—", "sloupců": "—", "platnost": "", "pozn": str(e)})
    display(HTML(f"<b style='color:red;'>❌ Agregace cash ratingu selhala:</b> {e}<br><pre>{traceback.format_exc()}</pre>"))
    transakce_trn_agg = pd.DataFrame(columns=['BRANCH_CODE', 'TRN_POCET_CELKEM', 'TRN_CASTKA_CELKEM', 'TRN_DENNI_POCET'])

# ── Pokladní hodiny — počet otevřených dní na pobočku ─────────────────────────
# Slouží pro přesný výpočet TRN_DENNI_POCET (náhrada konstanty WORKING_DAYS_PER_YEAR)
try:
    import datetime as _dt
    _ph_path = soubory["pokladni_hodiny"]["path"]
    _ph_raw  = pd.read_excel(_ph_path)
    _ph_day_cols = [c for c in ['PO','UT','ST','CT','PA','SO','NE'] if c in _ph_raw.columns]
    if _ph_day_cols and 'BRANCH_ID' in _ph_raw.columns:
        def _is_open(v):
            # Hodnoty jsou řetězce "HH:MM"; "00:00" = zavřeno
            if isinstance(v, _dt.time):
                return (v.hour + v.minute) > 0
            if isinstance(v, (int, float)):
                import math
                return not (v == 0 or (isinstance(v, float) and math.isnan(v)))
            s = str(v).strip()
            return bool(s) and s not in ('00:00', '0:00', 'nan', 'None', 'NaT', '', '0')
        _ph_raw['_open_days'] = _ph_raw[_ph_day_cols].apply(
            lambda row: sum(1 for v in row if _is_open(v)), axis=1
        )
        _ph_raw['BRANCH_ID'] = pd.to_numeric(_ph_raw['BRANCH_ID'], errors='coerce')
        # Roční dny = open_days_per_week / 7 * 365
        _ph_raw['_annual_days'] = (_ph_raw['_open_days'] / 7 * 365).round(0).astype(int).clip(lower=1)
        pokladni_dny = dict(zip(_ph_raw['BRANCH_ID'].dropna().astype(int), _ph_raw['_annual_days']))
        _avg_days = sum(pokladni_dny.values()) / max(len(pokladni_dny), 1)
        _load_log.append({"jmeno": "pokladni_hodiny", "status": "✅", "typ": "XLSX",
            "řádků": f"{len(_ph_raw):,}", "sloupců": str(len(_ph_raw.columns)),
            "platnost": soubory["pokladni_hodiny"]["validity"],
            "pozn": f"{len(pokladni_dny)} poboček · průměr {_avg_days:.0f} dní/rok · dělitel pro TRN_DENNI_POCET"})
        print(f"✅ Pokladní hodiny: {len(pokladni_dny)} poboček, průměr {_avg_days:.0f} dní/rok")
    else:
        pokladni_dny = {}
        _load_log.append({"jmeno": "pokladni_hodiny", "status": "⚠️", "typ": "XLSX",
            "řádků": f"{len(_ph_raw):,}", "sloupců": str(len(_ph_raw.columns)),
            "platnost": "", "pozn": f"chybí sloupce BRANCH_ID nebo PO/UT/… — nalezené: {list(_ph_raw.columns)[:8]}"})
        print("⚠️ Pokladní hodiny: chybí sloupce BRANCH_ID nebo PO/UT/…")
except Exception as _e:
    pokladni_dny = {}
    _load_log.append({"jmeno": "pokladni_hodiny", "status": "❌", "typ": "XLSX",
        "řádků": "—", "sloupců": "—", "platnost": "", "pozn": str(_e)})
    print(f"⚠️ Pokladní hodiny nenačteny: {_e}")

# ── Otevírací doba — hodiny a dny otevření pobočky ─────────────────────────
# Slouží pro zobrazení ot. doby v pobočkovém reportu a výpočet OD_NAVSTEVY_NA_HODINU
_OD_DAYS = [
    ('PONDELI', 'PO'), ('UTERY', 'UT'), ('STREDA', 'ST'),
    ('CTVRTEK', 'CT'), ('PATEK', 'PA'), ('SOBOTA', 'SO'), ('NEDELE', 'NE'),
]
oteviraci_doba_df     = pd.DataFrame()
oteviraci_doba_detail = {}
try:
    _od_path = soubory["oteviraci_doba"]["path"]
    _od_raw  = pd.read_excel(_od_path, dtype=str)
    if 'KOD_POBOCKY' in _od_raw.columns:
        _od_raw['_kp'] = pd.to_numeric(_od_raw['KOD_POBOCKY'], errors='coerce')
        _od_raw['OD_PH_TYDEN'] = pd.to_numeric(
            (_od_raw['PH'] if 'PH' in _od_raw.columns else pd.Series(['0'] * len(_od_raw)))
            .astype(str).str.replace(',', '.', regex=False),
            errors='coerce'
        ).fillna(0.0)

        def _od_is_vikend(r):
            return (str(r.get('SO', '')).strip() not in ('00:00', '0:00', '', 'nan')
                    or str(r.get('NE', '')).strip() not in ('00:00', '0:00', '', 'nan'))

        def _od_has_pauza(r):
            for _dn, _ in _OD_DAYS:
                _dd = str(r.get(f'{_dn}_DOP._DO', '')).strip()
                _oo = str(r.get(f'{_dn}_ODP._OD', '')).strip()
                if _dd not in ('00:00', '0:00', '', 'nan') and _dd != _oo:
                    return True
            return False

        _od_raw['OD_VIKEND']     = _od_raw.apply(_od_is_vikend, axis=1)
        _od_raw['OD_OBED_PAUZA'] = _od_raw.apply(_od_has_pauza, axis=1)

        _od_clean = _od_raw.dropna(subset=['_kp']).copy()
        _od_clean['_kp'] = _od_clean['_kp'].astype(int)
        for _, _r in _od_clean.iterrows():
            oteviraci_doba_detail[int(_r['_kp'])] = _r.to_dict()

        oteviraci_doba_df = _od_clean[['_kp', 'OD_PH_TYDEN', 'OD_VIKEND', 'OD_OBED_PAUZA']].rename(
            columns={'_kp': 'BRANCH_CODE'})
        _od_n = len(oteviraci_doba_df)
        _load_log.append({"jmeno": "oteviraci_doba", "status": "✅", "typ": "XLSX",
            "řádků": f"{len(_od_raw):,}", "sloupců": str(len(_od_raw.columns)),
            "platnost": soubory["oteviraci_doba"]["validity"],
            "pozn": f"{_od_n} poboček · ot. hodiny, víkend, polední pauza"})
        print(f"✅ Otevírací doba: {_od_n} poboček načteno")
    else:
        _load_log.append({"jmeno": "oteviraci_doba", "status": "⚠️", "typ": "XLSX",
            "řádků": f"{len(_od_raw):,}", "sloupců": str(len(_od_raw.columns)),
            "platnost": "", "pozn": "chybí sloupec KOD_POBOCKY"})
        print("⚠️ Otevírací doba: chybí sloupec KOD_POBOCKY")
except Exception as _ode:
    _load_log.append({"jmeno": "oteviraci_doba", "status": "❌", "typ": "XLSX",
        "řádků": "—", "sloupců": "—", "platnost": "", "pozn": str(_ode)})
    print(f"⚠️ Otevírací doba nenačtena: {_ode}")

# ── Zobraz souhrnnou tabulku načtených datasetů ───────────────────────────────
_show_load_summary()


