        def _get_q_for_metric(qsrc):
            for suffix in ['_Q', '_STATUS', '_Q_HTML']:
                col = qsrc + suffix
                if col not in _brow.columns: continue
                v = _brow.iloc[0].get(col) if len(_brow) > 0 else None
